    if any(
        w in cl_low
        for w in [
            "supplier",
            "vendor",
            "creditor",
            "payable",
            "purchase",
            "trade payable",
        ]
    ):
        target_kws = [
            "trade creditor",
            "accounts payable",
            "trade payable",
            "creditor",
            "payable",
            "supplier",
        ]
