        "amount": amt,
        "is_debit": cash_is_debit,
        "transaction_type": cash_acc,
    }
    line_cp = {
        "batch": batch_id,
        "amount": amt,
        "is_debit": cp_is_debit,
        "transaction_type": cp_acc,
    }

    # Convention: debit first, credit second
    if cash_is_debit:
        row["journal_lines"] = [line_cash, line_cp]
    else:
        row["journal_lines"] = [line_cp, line_cash]

