# 2. Account Finder Functions
def get_holding_account():
    priority_phrases = [
        "holding account",
        "suspense account",
        "suspense",
        "holding",
        "unallocated receipts",
        "unallocated payments",
        "unallocated cash",
        "unallocated",
        "unidentified receipts",
        "unidentified",
        "parked transactions",
        "parked",
        "clearing account",
        "general suspense",
    ]
    # Exact / full phrase match
    for phrase in priority_phrases:
        for tt in all_trans_types:
            if phrase == tt.lower().strip():
                return tt

    # Substring match
    for phrase in priority_phrases:
        for tt in all_trans_types:
            if phrase in tt.lower():
                return tt

    # Broader fallback
    for tt in all_trans_types:
        if "susp" in tt.lower() or "hold" in tt.lower():
            return tt

    return all_trans_types[0] if all_trans_types else None


def get_cash_account(currency):
    cur = (currency or "GBP").upper()
    disqualifiers = [
        "fee",
        "charge",
        "interest",
        "loan",
        "suspense",
        "holding",
        "payable",
        "receivable",
        "debtor",
        "creditor",
        "clearing",
        "settlement",
    ]

    best = None
    best_score = -999

    for r in coa_records:
        tt = str(r.get(tt_col, "")).strip()
        text = " ".join(str(v) for v in r.values()).lower()
        tt_low = tt.lower()

        if any(d in tt_low for d in disqualifiers):
            continue

        score = 0
        if cur.lower() in tt_low:
            score += 50
        elif cur.lower() in text:
            score += 30

        if "bank" in tt_low:
            score += 30
        elif "bank" in text:
            score += 15

        if "cash" in tt_low:
            score += 25
        elif "cash" in text:
            score += 10

        if "current" in tt_low or "operating" in tt_low:
            score += 15

        if "bank" not in tt_low and "cash" not in tt_low:
            score -= 40

        if score > best_score:
            best_score = score
            best = tt

    if best and best_score > 0:
        return best

    for tt in all_trans_types:
        if "bank" in tt.lower():
            return tt
    for tt in all_trans_types:
        if "cash" in tt.lower():
            return tt

    return all_trans_types[0] if all_trans_types else None


def get_counterpart_account(
    classification, currency, is_statement_credit, holding_acc
):
    cl = (classification or "").strip()
    cl_low = cl.lower()
    cur_low = (currency or "").lower()

    # Direct match on classification
    for tt in all_trans_types:
        if kit.compact(tt) == kit.compact(cl):
            return tt

    target_keywords = []
    if any(
        w in cl_low
        for w in [
            "supplier",
            "vendor",
            "creditor",
            "payable",
            "purchase",
            "trade payable",
            "expense",
        ]
    ):
        target_keywords = [
            "trade creditor",
            "accounts payable",
            "trade payable",
            "creditor",
            "payable",
            "supplier",
            "purchases",
        ]
    elif any(
        w in cl_low
        for w in [
            "customer",
            "client",
            "debtor",
            "receivable",
            "sales",
            "trade receivable",
            "income",
            "revenue",
        ]
    ):
        target_keywords = [
            "trade debtor",
            "accounts receivable",
            "trade receivable",
            "debtor",
            "receivable",
            "customer",
            "sales",
            "revenue",
        ]
    elif any(w in cl_low for w in ["payroll", "wage", "salaries", "salary"]):
        target_keywords = ["payroll", "wages", "salaries", "salary"]
    elif any(w in cl_low for w in ["tax", "vat", "hmrc"]):
        target_keywords = ["vat", "tax", "hmrc", "corporation tax"]
    elif any(w in cl_low for w in ["interest", "finance"]):
        target_keywords = ["interest", "finance"]
    elif any(w in cl_low for w in ["fee", "bank charge"]):
        target_keywords = ["bank charge", "bank fee", "fee"]
    else:
        if is_statement_credit:
            target_keywords = [
                "trade debtor",
                "accounts receivable",
                "trade receivable",
                "debtor",
                "receivable",
                "sales",
            ]
        else:
            target_keywords = [
                "trade creditor",
                "accounts payable",
                "trade payable",
                "creditor",
                "payable",
                "supplier",
            ]

    best = None
    best_score = -999
    disqualifiers = [
        "bank",
        "cash",
        "suspense",
        "holding",
        "clearing",
        "settlement",
    ]

    for r in coa_records:
        tt = str(r.get(tt_col, "")).strip()
        text = " ".join(str(v) for v in r.values()).lower()
        tt_low = tt.lower()

        if any(d in tt_low for d in disqualifiers):
            continue

        score = 0
        for i, kw in enumerate(target_keywords):
            if kw == tt_low:
                score += 50 - i * 2
                break
            elif kw in tt_low:
                score += 30 - i * 2
                break
            elif kw in text:
                score += 15 - i * 2
                break

        if score > 0:
            if cur_low and (cur_low in tt_low or cur_low in text):
                score += 10
            if score > best_score:
                best_score = score
                best = tt

    return best if (best and best_score > 0) else holding_acc


